C++PythonJavaScript <pre><code>class Solution {
public:
    vector&lt;int&gt; twoSum(vector&lt;int&gt;&amp; nums, int target) {
        unordered_map&lt;int, int&gt; um;                             // value → index
        for (int i = 0; i &lt; (int)nums.size(); i++) {
            if (um.find(target - nums[i]) != um.end()) {
                return {i, um[target - nums[i]]};               // 命中: 返 (当前, 之前)
            }
            um[nums[i]] = i;                                    // 记账
        }
        return {};
    }
};
</code></pre> <pre><code>class Solution:
    def twoSum(self, nums: list[int], target: int) -&gt; list[int]:
        # dict = hash map. enumerate 一次拿 index+value, 比 for i in range(len(nums)) 干净
        seen: dict[int, int] = {}
        for i, x in enumerate(nums):
            # 海象运算符 := (Python 3.8+): 赋值 + 表达式一步. 相当于 C++ if (auto c = ...; ...)
            # 语义: 算 c 后立刻检查 c in seen
            if (c := target - x) in seen:
                return [seen[c], i]
            seen[x] = i
        return []
</code></pre> <pre><code>/**
 * @param {number[]} nums
 * @param {number} target
 * @return {number[]}
 */
var twoSum = function(nums, target) {
    // Map 而不是 Object — Map 保留数字 key 类型 (Object 会把 key 转 string), 也更接近 C++ unordered_map
    const seen = new Map();
    for (let i = 0; i &lt; nums.length; i++) {
        const c = target - nums[i];
        // .has() O(1) 平均查, 跟 C++ .find() != .end() 等价
        if (seen.has(c)) return [seen.get(c), i];
        seen.set(nums[i], i);
    }
    return [];
};
</code></pre>

C++PythonJavaScript <p>v1: 按圈模拟 + 左闭右开 (Yang 风格)</p> <pre><code>class Solution {
public:
    vector&lt;vector&lt;int&gt;&gt; generateMatrix(int n) {
        vector&lt;vector&lt;int&gt;&gt; res(n, vector&lt;int&gt;(n));
        int i, j;
        int startx = 0, starty = 0;
        int offset = 1, count = 1;
        int loop = n / 2, mid = n / 2;
        while (loop--) {
            i = startx;
            j = starty;
            for (j; j &lt; n - offset; j++) res[i][j] = count++;           // 上: [starty, n-offset)
            for (i; i &lt; n - offset; i++) res[i][j] = count++;           // 右
            for (j; j &gt; starty;    j--) res[i][j] = count++;            // 下
            for (i; i &gt; startx;    i--) res[i][j] = count++;            // 左
            startx++; starty++; offset++;                                // 收缩一圈
        }
        if (n % 2 == 1) res[mid][mid] = count;                          // n 奇: 补中心
        return res;
    }
};
</code></pre> <p>v2: 方向数组 + 遇墙转 (更通用)</p> <pre><code>class Solution {
public:
    vector&lt;vector&lt;int&gt;&gt; generateMatrix(int n) {
        vector&lt;vector&lt;int&gt;&gt; mat(n, vector&lt;int&gt;(n, 0));
        vector&lt;pair&lt;int,int&gt;&gt; dirs = {{0,1}, {1,0}, {0,-1}, {-1,0}};    // 右下左上
        int dir = 0, r = 0, c = 0;
        for (int num = 1; num &lt;= n * n; num++) {
            mat[r][c] = num;
            int nr = r + dirs[dir].first;
            int nc = c + dirs[dir].second;
            if (nr &lt; 0 || nr &gt;= n || nc &lt; 0 || nc &gt;= n || mat[nr][nc] != 0) {
                dir = (dir + 1) % 4;                                    // 遇墙/已填 → 转 90°
                nr = r + dirs[dir].first;
                nc = c + dirs[dir].second;
            }
            r = nr; c = nc;
        }
        return mat;
    }
};
</code></pre> <pre><code>class Solution:
    def generateMatrix(self, n: int) -&gt; list[list[int]]:
        # v2 风格 — Python 写起来比 v1 干净
        mat = [[0] * n for _ in range(n)]
        # 方向数组: 顺时针 右↓左↑. 对应 C++ pair&lt;int,int&gt;
        dirs = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        d = 0
        r = c = 0
        for num in range(1, n * n + 1):
            mat[r][c] = num
            nr, nc = r + dirs[d][0], c + dirs[d][1]
            # 越界或已填 → 转向. `not 0 &lt;= nr &lt; n` 比 `nr &lt; 0 or nr &gt;= n` 更 Pythonic
            if not (0 &lt;= nr &lt; n and 0 &lt;= nc &lt; n) or mat[nr][nc] != 0:
                d = (d + 1) % 4
                nr, nc = r + dirs[d][0], c + dirs[d][1]
            r, c = nr, nc
        return mat
</code></pre> <pre><code>/**
 * @param {number} n
 * @return {number[][]}
 */
var generateMatrix = function(n) {
    // v2 风格. JS 用 Array.from 二维初始化 — 必须用工厂函数, 不能 fill([0]) (会共享同一引用)
    const mat = Array.from({length: n}, () =&gt; new Array(n).fill(0));
    const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
    let d = 0, r = 0, c = 0;
    for (let num = 1; num &lt;= n * n; num++) {
        mat[r][c] = num;
        let nr = r + dirs[d][0];
        let nc = c + dirs[d][1];
        if (nr &lt; 0 || nr &gt;= n || nc &lt; 0 || nc &gt;= n || mat[nr][nc] !== 0) {
            d = (d + 1) % 4;        // 转向公式: (d + 1) % 4
            nr = r + dirs[d][0];
            nc = c + dirs[d][1];
        }
        r = nr;
        c = nc;
    }
    return mat;
};
</code></pre>

C++PythonJavaScript <p>v1: 显式 left + right 数组 (思路最清晰)</p> <pre><code>class Solution {
public:
    vector&lt;int&gt; productExceptSelf(vector&lt;int&gt;&amp; nums) {
        int n = nums.size();
        vector&lt;int&gt; left(n, 1), right(n, 1), ans(n);
        for (int i = 1; i &lt; n; i++) left[i] = left[i - 1] * nums[i - 1];       // 左前缀积
        for (int i = n - 2; i &gt;= 0; i--) right[i] = right[i + 1] * nums[i + 1]; // 右后缀积
        for (int i = 0; i &lt; n; i++) ans[i] = left[i] * right[i];
        return ans;
    }
};
</code></pre> <p>v2: ans 复用 + scalar (O(1) 额外空间)</p> <pre><code>class Solution {
public:
    vector&lt;int&gt; productExceptSelf(vector&lt;int&gt;&amp; nums) {
        int n = nums.size();
        vector&lt;int&gt; ans(n, 1);
        // 第一遍: ans[i] 存"i 左边的积"
        for (int i = 1; i &lt; n; i++) ans[i] = ans[i - 1] * nums[i - 1];
        // 第二遍: right 累积"i 右边的积", 直接乘进 ans[i]
        int right = 1;
        for (int i = n - 1; i &gt;= 0; i--) {
            ans[i] *= right;
            right *= nums[i];
        }
        return ans;
    }
};
</code></pre> <pre><code>class Solution:
    def productExceptSelf(self, nums: list[int]) -&gt; list[int]:
        # v2: O(1) extra space. 直接对应 C++ v2
        # 注意 Python 没有 vector&lt;int&gt;(n, 1) 这种语法, 用列表乘法 [1] * n
        n = len(nums)
        ans = [1] * n
        # 第一遍: 左前缀积
        for i in range(1, n):
            ans[i] = ans[i - 1] * nums[i - 1]
        # 第二遍: 右后缀积用 scalar 累积. enumerate 不需要, 反向 range 更直观
        right = 1
        for i in range(n - 1, -1, -1):
            ans[i] *= right
            right *= nums[i]
        return ans
</code></pre> <pre><code>/**
 * @param {number[]} nums
 * @return {number[]}
 */
var productExceptSelf = function(nums) {
    // v2: O(1) extra space
    const n = nums.length;
    // new Array(n).fill(1) — 基本类型 fill 没"共享引用" 坑, 这里安全
    const ans = new Array(n).fill(1);
    // 第一遍: 左前缀积
    for (let i = 1; i &lt; n; i++) ans[i] = ans[i - 1] * nums[i - 1];
    // 第二遍: 右扫 + scalar
    let right = 1;
    for (let i = n - 1; i &gt;= 0; i--) {
        ans[i] *= right;
        right *= nums[i];
    }
    return ans;
};
</code></pre>

C++PythonJavaScript <pre><code>class NumArray {
    vector&lt;int&gt; prefix;                                        // prefix[i] = nums[0..i-1] 之和 (哨兵)
public:
    NumArray(vector&lt;int&gt;&amp; nums) {
        int n = nums.size();
        prefix.assign(n + 1, 0);                               // prefix[0] = 0 哨兵, 其余先填 0
        for (int i = 0; i &lt; n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];               // 递推一行
        }
    }
    int sumRange(int left, int right) {
        return prefix[right + 1] - prefix[left];               // 闭区间和 = prefix[r+1] - prefix[l]
    }
};
</code></pre> <pre><code>from itertools import accumulate

class NumArray:
    def __init__(self, nums: list[int]):
        # accumulate(nums, initial=0): 一行做前缀和 + 哨兵
        # initial=0 等价 C++ 手动写 prefix[0] = 0; 返回长度 n+1 的迭代器
        # 等价 for 循环: prefix = [0]; for x in nums: prefix.append(prefix[-1] + x)
        self.prefix = list(accumulate(nums, initial=0))

    def sumRange(self, left: int, right: int) -&gt; int:
        return self.prefix[right + 1] - self.prefix[left]
</code></pre> <pre><code>/**
 * @param {number[]} nums
 */
var NumArray = function(nums) {
    // 一开就 length+1, 第 0 位天然 0 (JS new Array(n) 配合 fill 是 undefined, 这里直接累加更稳)
    this.prefix = new Array(nums.length + 1).fill(0);
    for (let i = 0; i &lt; nums.length; i++) {
        this.prefix[i + 1] = this.prefix[i] + nums[i];
    }
};

/**
 * @param {number} left
 * @param {number} right
 * @return {number}
 */
NumArray.prototype.sumRange = function(left, right) {
