C++PythonJavaScript <pre><code>class NumMatrix {
    vector&lt;vector&lt;int&gt;&gt; prefix;                                // (m+1) × (n+1) 带哨兵
public:
    NumMatrix(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) {
        int m = matrix.size(), n = matrix[0].size();
        prefix.assign(m + 1, vector&lt;int&gt;(n + 1, 0));
        for (int i = 0; i &lt; m; i++) {
            for (int j = 0; j &lt; n; j++) {
                prefix[i + 1][j + 1] = prefix[i][j + 1]        // 上块
                                     + prefix[i + 1][j]        // 左块
                                     - prefix[i][j]            // 重叠减回
                                     + matrix[i][j];           // 当前格
            }
        }
    }
    int sumRegion(int r1, int c1, int r2, int c2) {
        return prefix[r2 + 1][c2 + 1]
             - prefix[r1][c2 + 1]                              // 上条
             - prefix[r2 + 1][c1]                              // 左条
             + prefix[r1][c1];                                 // 左上角加回
    }
};
</code></pre> <pre><code>class NumMatrix:
    def __init__(self, matrix: list[list[int]]):
        m, n = len(matrix), len(matrix[0])
        # 列表推导建 (m+1) × (n+1) 零矩阵: 注意不能用 [[0]*(n+1)]*(m+1), 那是浅拷贝, 所有行指向同一个 list
        self.prefix = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            for j in range(n):
                self.prefix[i + 1][j + 1] = (
                    self.prefix[i][j + 1]
                    + self.prefix[i + 1][j]
                    - self.prefix[i][j]
                    + matrix[i][j]
                )

    def sumRegion(self, r1: int, c1: int, r2: int, c2: int) -&gt; int:
        p = self.prefix
        return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1]
</code></pre> <pre><code>/**
 * @param {number[][]} matrix
 */
var NumMatrix = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    // Array.from + 工厂函数: 每行独立 new Array, 避免 fill(arr) 的浅引用陷阱 (类似 Python 的 [...]*n 坑)
    this.prefix = Array.from({ length: m + 1 }, () =&gt; new Array(n + 1).fill(0));
    for (let i = 0; i &lt; m; i++) {
        for (let j = 0; j &lt; n; j++) {
            this.prefix[i + 1][j + 1] = this.prefix[i][j + 1]
                                      + this.prefix[i + 1][j]
                                      - this.prefix[i][j]
                                      + matrix[i][j];
        }
    }
};

/**
 * @param {number} row1
 * @param {number} col1
 * @param {number} row2
 * @param {number} col2
 * @return {number}
 */
NumMatrix.prototype.sumRegion = function(r1, c1, r2, c2) {
    const p = this.prefix;
    return p[r2 + 1][c2 + 1] - p[r1][c2 + 1] - p[r2 + 1][c1] + p[r1][c1];
};
</code></pre>

C++PythonJavaScript <pre><code>class Solution {
public:
    vector&lt;int&gt; getModifiedArray(int length, vector&lt;vector&lt;int&gt;&gt;&amp; updates) {
        vector&lt;int&gt; diff(length + 1, 0);                       // +1 给 end+1 可能 == length 留槽位
        for (auto&amp; u : updates) {
            diff[u[0]]     += u[2];                            // [start, end] +inc → diff[start] +inc
            diff[u[1] + 1] -= u[2];                            //                    → diff[end+1] -inc
        }
        vector&lt;int&gt; res(length);
        res[0] = diff[0];
        for (int i = 1; i &lt; length; i++) {
            res[i] = res[i - 1] + diff[i];                     // 前缀和复原
        }
        return res;
    }
};
</code></pre> <pre><code>from itertools import accumulate

class Solution:
    def getModifiedArray(self, length: int, updates: list[list[int]]) -&gt; list[int]:
        diff = [0] * (length + 1)                              # +1 哨兵, 避免 end+1 越界
        for start, end, inc in updates:                        # 解包三元组
            diff[start]   += inc
            diff[end + 1] -= inc
        # accumulate(diff) 一行算前缀和, 然后切片到 length (去掉哨兵那一格)
        # list(...) 因为 accumulate 返回迭代器
        return list(accumulate(diff))[:length]
</code></pre> <pre><code>/**
 * @param {number} length
 * @param {number[][]} updates
 * @return {number[]}
 */
var getModifiedArray = function(length, updates) {
    const diff = new Array(length + 1).fill(0);
    for (const [start, end, inc] of updates) {                 // 数组解构 + for...of
        diff[start]     += inc;
        diff[end + 1]   -= inc;
    }
    const res = new Array(length);
    res[0] = diff[0];
    for (let i = 1; i &lt; length; i++) {
        res[i] = res[i - 1] + diff[i];                         // 前缀和
    }
    return res;
};
</code></pre>

C++PythonJavaScript <pre><code>class Solution {
public:
    bool checkSubarraySum(vector&lt;int&gt;&amp; nums, int k) {
        unordered_map&lt;int, int&gt; firstIdx;
        firstIdx[0] = 0;                                         // 哨兵: 空前缀 boundary 0
        int sum = 0;
        for (int i = 0; i &lt; (int)nums.size(); ++i) {
            sum = (sum + nums[i]) % k;
            if (sum &lt; 0) sum += k;                               // 负数守卫 (防御性)
            int boundary = i + 1;                                // 消耗 nums[i] 后的边界
            auto it = firstIdx.find(sum);
            if (it != firstIdx.end()) {
                if (boundary - it-&gt;second &gt;= 2) return true;     // 长度 ≥ 2
                // 已存在 → 保留最早的 (不覆盖)
            } else {
                firstIdx[sum] = boundary;
            }
        }
        return false;
    }
};
</code></pre> <pre><code>class Solution:
    def checkSubarraySum(self, nums: list[int], k: int) -&gt; bool:
        first_idx = {0: 0}      # 哨兵
        s = 0
        for i, x in enumerate(nums):
            s = (s + x) % k     # Python % 对负数返正 (数学定义) — 天然安全
            boundary = i + 1
            if s in first_idx:
                if boundary - first_idx[s] &gt;= 2:
                    return True
                # 已存在, 不覆盖 (保留最早)
            else:
                first_idx[s] = boundary
        return False
</code></pre> <pre><code>/**
 * @param {number[]} nums
 * @param {number} k
 * @return {boolean}
 */
var checkSubarraySum = function(nums, k) {
    const firstIdx = new Map();
    firstIdx.set(0, 0);
    let sum = 0;
    for (let i = 0; i &lt; nums.length; i++) {
        sum = (sum + nums[i]) % k;
        // JS % 对负数返负 (跟 C++ 同), 严格需要 +k 兜; 本题 nums 全非负故省
        if (sum &lt; 0) sum += k;
        const boundary = i + 1;
        if (firstIdx.has(sum)) {
            if (boundary - firstIdx.get(sum) &gt;= 2) return true;
        } else {
            firstIdx.set(sum, boundary);
        }
    }
    return false;
};
</code></pre>

C++PythonJavaScript <pre><code>class Solution {
public:
    int findMaxLength(vector&lt;int&gt;&amp; nums) {
        unordered_map&lt;int, int&gt; idx;
        int maxLen = 0, sum = 0;
        idx[0] = -1;                                             // 哨兵: 让从 0 开始的整段 dist = i + 1

        for (int i = 0; i &lt; (int)nums.size(); i++) {
            sum += (nums[i] == 1) ? 1 : -1;                      // 映射: 0 → -1, 1 → +1

            auto it = idx.find(sum);
            if (it != idx.end()) {
                maxLen = max(maxLen, i - it-&gt;second);            // 更新最长
            } else {
                idx[sum] = i;                                    // 只存首次
            }
        }
        return maxLen;
    }
};
</code></pre> <pre><code>class Solution:
    def findMaxLength(self, nums: list[int]) -&gt; int:
        idx = {0: -1}       # 哨兵
        max_len = s = 0
        for i, x in enumerate(nums):
            s += 1 if x == 1 else -1
            if s in idx:
                max_len = max(max_len, i - idx[s])
            else:
                idx[s] = i
        return max_len
</code></pre> <pre><code>/**
 * @param {number[]} nums
 * @return {number}
 */
var findMaxLength = function(nums) {
    const idx = new Map();
    idx.set(0, -1);         // 哨兵
    let maxLen = 0, sum = 0;
    for (let i = 0; i &lt; nums.length; i++) {
        sum += nums[i] === 1 ? 1 : -1;
        if (idx.has(sum)) {
            maxLen = Math.max(maxLen, i - idx.get(sum));
        } else {
            idx.set(sum, i);
        }
    }
    return maxLen;
};
</code></pre>

C++PythonJavaScript <pre><code>class Solution {
    vector&lt;int&gt; prefix;
    int total;
public:
    Solution(vector&lt;int&gt;&amp; w) {
        prefix.resize(w.size());
        prefix[0] = w[0];
        for (int i = 1; i &lt; (int)w.size(); i++) {
            prefix[i] = prefix[i - 1] + w[i];                  // 累积权重
        }
        total = prefix.back();
    }
    int pickIndex() {
        int target = rand() % total + 1;                       // target ∈ [1, total]
        int left = 0, right = prefix.size() - 1;
        while (left &lt; right) {                                 // lower_bound: 找第一个 prefix[i] &gt;= target
            int mid = left + (right - left) / 2;
            if (prefix[mid] &lt; target) left = mid + 1;          // mid 太小, 排除
            else                       right = mid;             // mid 可能就是答案, 保留
        }
        return left;
    }
};
</code></pre> <pre><code>import random
from bisect import bisect_left

class Solution:
    def __init__(self, w: list[int]):
        # accumulate(w): 一行算前缀和 (无初始 0); 这里需要 prefix[0] = w[0], 所以不加 initial
        from itertools import accumulate
        self.prefix = list(accumulate(w))
        self.total  = self.prefix[-1]

    def pickIndex(self) -&gt; int:
        # random.randint(a, b): 闭区间 [a, b], 等价 C++ 的 rand() % total + 1
        target = random.randint(1, self.total)
        # bisect_left = 找第一个 &gt;= target 的位置, 等价手写 lower_bound. 比手写二分 3 倍快且不会写错
        return bisect_left(self.prefix, target)
</code></pre> <pre><code>/**
 * @param {number[]} w
 */
var Solution = function(w) {
    this.prefix = new Array(w.length);
    this.prefix[0] = w[0];
    for (let i = 1; i &lt; w.length; i++) {
        this.prefix[i] = this.prefix[i - 1] + w[i];
    }
    this.total = this.prefix[this.prefix.length - 1];
};

/**
 * @return {number}
 */
Solution.prototype.pickIndex = function() {
    // Math.random() ∈ [0, 1), * total → [0, total), Math.floor 取整 → [0, total-1], +1 → [1, total]
    const target = Math.floor(Math.random() * this.total) + 1;
    let left = 0, right = this.prefix.length - 1;
    while (left &lt; right) {                                     // lower_bound 模板
        const mid = (left + right) &gt;&gt; 1;                       // &gt;&gt;1 等价 /2 取整, 比 Math.floor 快
        if (this.prefix[mid] &lt; target) left = mid + 1;
        else                            right = mid;
    }
    return left;
};
</code></pre>

C++PythonJavaScript <pre><code>class Solution {
public:
    int subarraySum(vector&lt;int&gt;&amp; nums, int k) {
        unordered_map&lt;long long, int&gt; cnt;
        cnt[0] = 1;                                              // 哨兵: 空前缀
        long long sum = 0;
        int res = 0;
