        if val not in self.idx:
            return False
        i, last = self.idx[val], self.arr[-1]
        # swap-with-last: 把末位搬到 i, 弹末位
        self.arr[i] = last
        self.idx[last] = i               # 更新末位元素的新下标
        self.arr.pop()                   # O(1)
        del self.idx[val]                # dict 的 del 是 O(1)
