C++PythonJavaScript <p>v1: Trie + DFS + memo</p> <pre><code>class Solution {
    struct TrieNode {
        TrieNode* children[26] = {nullptr};
        bool isEnd = false;
    };
    TrieNode* root = new TrieNode();

    void insert(const string&amp; s) {
        TrieNode* cur = root;
        for (char c : s) {
            int idx = c - 'a';
            if (!cur-&gt;children[idx]) cur-&gt;children[idx] = new TrieNode();
            cur = cur-&gt;children[idx];
        }
        cur-&gt;isEnd = true;
    }

    bool dfs(const string&amp; word, int start, bool isFirst, vector&lt;int&gt;&amp; memo) {
        int n = word.size();
        if (start == n) return true;
        if (memo[start] != -1) return memo[start];

        TrieNode* cur = root;
        for (int i = start; i &lt; n; i++) {
            cur = cur-&gt;children[word[i] - 'a'];
            if (!cur) break;
            if (cur-&gt;isEnd) {
                if (isFirst &amp;&amp; i == n - 1) continue;        // 灵魂守护: 整词 1 段 不算
                if (dfs(word, i + 1, false, memo)) {
                    memo[start] = 1;
                    return true;
                }
            }
        }
        memo[start] = 0;
        return false;
    }

public:
    vector&lt;string&gt; findAllConcatenatedWordsInADict(vector&lt;string&gt;&amp; words) {
        for (string&amp; w : words) insert(w);
        vector&lt;string&gt; res;
        for (string&amp; w : words) {
            vector&lt;int&gt; memo(w.size(), -1);
            if (dfs(w, 0, true, memo)) res.push_back(w);
        }
        return res;
    }
};
