private:
    vector&lt;int&gt; getNext(const string&amp; s) {
        int n = s.size();
        vector&lt;int&gt; next(n, 0);
        int j = 0;                                              // 当前候选前缀末位
        for (int i = 1; i &lt; n; i++) {
            while (j &gt; 0 &amp;&amp; s[i] != s[j])
                j = next[j - 1];                                // 失配, 沿 next 回退
            if (s[i] == s[j]) j++;                              // 匹配, 前缀延长
            next[i] = j;
        }
        return next;
    }
};

