                        i--;
                    }
                    i++; j++;                                           // 退过头, 修正
                    int left = i;

                    if (right - left + 1 &lt; bestLen) {                   // 更新答案
                        bestLen = right - left + 1;
                        bestStart = left;
                    }
                    // ⚠ 跳到 left + 1 而不是 right + 1, 防漏重叠窗
                    i = left + 1;
                    j = 0;
                    continue;
                }
            }
            i++;
        }
        return bestStart == -1 ? "" : s1.substr(bestStart, bestLen);
    }
