PythonC++Java <p>Idiomatic Python: store indices in the deque (not values). Then "is the front out of window?" becomes a one-line index check, no need for the C++ value-equality dance.</p> <pre><code>from collections import deque

class Solution:
    def maxSlidingWindow(self, nums: list[int], k: int) -&gt; list[int]:
        dq: deque[int] = deque()   # indices; nums[dq[0]] is current window max
        res: list[int] = []
        for i, x in enumerate(nums):
            # 1) keep deque monotonically decreasing — kick smaller tails
            while dq and nums[dq[-1]] &lt; x:
                dq.pop()
            dq.append(i)
            # 2) front out of window?
            if dq[0] &lt;= i - k:
                dq.popleft()
            # 3) once first window is full, start emitting
            if i &gt;= k - 1:
                res.append(nums[dq[0]])
        return res
