        // 维持单调递减: 队尾比 value 小的都踢掉, 再把 value 放进队尾
        void push(int value) {
            while (!que.empty() &amp;&amp; value &gt; que.back()) {
                que.pop_back();
            }
            que.push_back(value);
        }
