public:
    vector&lt;int&gt; maxSlidingWindow(vector&lt;int&gt;&amp; nums, int k) {
        MyQueue que;
        vector&lt;int&gt; res;
        for (int i = 0; i &lt; k; i++) que.push(nums[i]);
        res.push_back(que.front());
        for (int i = k; i &lt; (int)nums.size(); i++) {
            que.pop(nums[i - k]);   // 移除窗口左边离开的元素
            que.push(nums[i]);       // 加入窗口右边新进来的元素
            res.push_back(que.front());
        }
