            if (used[i]) continue;
            if (i &gt; 0 &amp;&amp; half[i] === half[i - 1] &amp;&amp; !used[i - 1]) continue;
            used[i] = true;
            path.push(half[i]);
            backtrack();
            path.pop();
            used[i] = false;
        }
    };
    backtrack();
    return res;
