    bool check(const string&amp; num, int i, string s1, string s2) {
        if (i == (int)num.size()) return true;
        string sum = addStrings(s1, s2);
        if (i + (int)sum.size() &gt; (int)num.size()) return false;
        if (num.substr(i, sum.size()) != sum) return false;
