    // 链式消除: 找第一个 ≥ 3 段消除, 递归直到无.
    string shrink(string s) {
        for (int i = 0, j = 0; i &lt; (int)s.size(); i = j) {
            while (j &lt; (int)s.size() &amp;&amp; s[j] == s[i]) j++;
            if (j - i &gt;= 3) return shrink(s.substr(0, i) + s.substr(j));
        }
        return s;
