        if (get(tails, x - 1) &gt; 0) {                           // 接龙
            inc(count, x, -1);
            inc(tails, x - 1, -1);
            inc(tails, x, 1);
        } else if (get(count, x + 1) &gt; 0 &amp;&amp; get(count, x + 2) &gt; 0) {
            inc(count, x, -1);
            inc(count, x + 1, -1);
            inc(count, x + 2, -1);
