        while (l &gt;= 0 &amp;&amp; r &lt; n &amp;&amp; s[l] === s[r]) {
            l--; r++;
        }
        if (r - l - 1 &gt; maxLen) {
            start = l + 1;
            maxLen = r - l - 1;
        }
    };
    for (let i = 0; i &lt; n; i++) {
