        for (int len = 2; len &lt;= n; len++) {                                  // 按区间长度
            for (int i = 0; i + len - 1 &lt; n; i++) {
                int j = i + len - 1;

                // (a) 分裂转移: p ≥ 2
                for (int p = 2; p &lt;= k; p++) {
                    for (int mid = i; mid &lt; j; mid += k - 1) {                // ⚠ 步长 k-1
                        if (dp[i][mid][1] != INT_MAX
                            &amp;&amp; dp[mid + 1][j][p - 1] != INT_MAX) {
                            dp[i][j][p] = min(dp[i][j][p],
