                        }
                    }
                }

                // (b) k 堆 → 1 堆 (一次大合并, 代价 = 区间总和)
                if (dp[i][j][k] != INT_MAX) {
                    dp[i][j][1] = dp[i][j][k] + prefix[j + 1] - prefix[i];
                }
            }
        }
