        for sl in left_sums:
            target_r = goal - sl
            # bisect_left = C++ lower_bound, 返回首个 ≥ target 的索引
            idx = bisect_left(right_sums, target_r)
            for d in (-1, 0):
                i = idx + d
                if 0 &lt;= i &lt; len(right_sums):
                    result = min(result, abs(sl + right_sums[i] - goal))
        return result
