                int rightBound = j;                            // 右边第一个 ≤ arr[i]
                long cnt = (long)(i - leftBound) * (rightBound - i);
                ans = (ans + arr[i] * cnt) % MOD;
            }
            stk.push(j);
        }
        return (int)ans;
    }
