            }
            // sum[j] = 以 j 为右端点的所有子数组最小值之和
            vector&lt;int&gt; sum(n, 0);
            stack&lt;int&gt; stk;                                // 单调递增栈 (存索引)
            for (int j = 0; j &lt; n; j++) {
                // 弹出 ≥ heights[j] 的栈顶, 它们的"被 j 取代为最小" 的贡献要重算
                while (!stk.empty() &amp;&amp; heights[stk.top()] &gt;= heights[j]) stk.pop();
                if (stk.empty()) {
                    sum[j] = heights[j] * (j + 1);
                } else {
                    int prev = stk.top();
                    sum[j] = sum[prev] + heights[j] * (j - prev);
                }
                stk.push(j);
                total += sum[j];
            }
        }
        return total;
    }
};
