            if (d &gt; dist[u]) continue;                     // 过期记录, 跳过
            for (auto&amp; [v, w] : graph[u]) {
                if (dist[u] + w &lt; dist[v]) {
                    dist[v] = dist[u] + w;
                    pq.push({dist[v], v});
                }
            }
        }

        int ans = 0;
        for (int v = 1; v &lt;= n; v++) {
            if (dist[v] == INT_MAX) return -1;
            ans = max(ans, dist[v]);
        }
        return ans;
