        // [...arr] spread 浅拷贝快照
        const prev = [...dist];
        for (const [u, v, p] of flights) {
            if (prev[u] !== Infinity) {
                dist[v] = Math.min(dist[v], prev[u] + p);
            }
        }
    }
    return dist[dst] === Infinity ? -1 : dist[dst];
