        for (let j = 0; j &lt; n; j++) {
            if (grid[i][j] === 1) {
                const a = dfs(i, j, id);
                areaOf.set(id, a);
                if (a &gt; maxArea) maxArea = a;
                id++;
            }
        }
    }
