C++PythonJavaScript <pre><code>class UnionFind {
    vector&lt;int&gt; parent, rank_;
public:
    UnionFind(int n) : parent(n), rank_(n, 0) {
        for (int i = 0; i &lt; n; i++) parent[i] = i;             // 自成一集
    }
    int find(int x) {
        // 路径压缩: 递归找根, 顺手把 x 挂到根
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx == ry) return;
        // 按秩合并: 矮树挂到高树
        if (rank_[rx] &lt; rank_[ry]) parent[rx] = ry;
        else if (rank_[rx] &gt; rank_[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank_[rx]++; }
    }
    bool connected(int x, int y) { return find(x) == find(y); }
};

class Solution {
public:
    bool validPath(int n, vector&lt;vector&lt;int&gt;&gt;&amp; edges, int source, int destination) {
        UnionFind uf(n);
        for (auto&amp; e : edges) uf.unite(e[0], e[1]);
        return uf.connected(source, destination);
    }
};
</code></pre> <pre><code>class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))                           # 等价 [0, 1, ..., n-1]
        self.rank = [0] * n

    def find(self, x: int) -&gt; int:
        # 路径压缩 — 迭代版避免深递归栈溢出
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        # 二次扫描把路径上每点挂到根
        while self.parent[x] != root:
            self.parent[x], x = root, self.parent[x]
        return root

    def unite(self, x: int, y: int) -&gt; None:
        rx, ry = self.find(x), self.find(y)
        if rx == ry:
            return
        # 按秩合并
        if self.rank[rx] &lt; self.rank[ry]:
            self.parent[rx] = ry
        elif self.rank[rx] &gt; self.rank[ry]:
            self.parent[ry] = rx
        else:
            self.parent[ry] = rx
            self.rank[rx] += 1

    def connected(self, x: int, y: int) -&gt; bool:
        return self.find(x) == self.find(y)


class Solution:
    def validPath(self, n: int, edges: list[list[int]], source: int, destination: int) -&gt; bool:
        uf = UnionFind(n)
        for u, v in edges:
            uf.unite(u, v)
        return uf.connected(source, destination)
</code></pre> <pre><code>class UnionFind {
    constructor(n) {
        this.parent = Array.from({length: n}, (_, i) =&gt; i);    // [0, 1, ..., n-1]
        this.rank = new Array(n).fill(0);
    }
    find(x) {
        if (this.parent[x] !== x) this.parent[x] = this.find(this.parent[x]);
        return this.parent[x];
    }
    unite(x, y) {
        const rx = this.find(x), ry = this.find(y);
        if (rx === ry) return;
        if (this.rank[rx] &lt; this.rank[ry]) this.parent[rx] = ry;
        else if (this.rank[rx] &gt; this.rank[ry]) this.parent[ry] = rx;
        else { this.parent[ry] = rx; this.rank[rx]++; }
    }
    connected(x, y) { return this.find(x) === this.find(y); }
}

/**
 * @param {number} n
 * @param {number[][]} edges
 * @param {number} source
 * @param {number} destination
 * @return {boolean}
 */
var validPath = function(n, edges, source, destination) {
    const uf = new UnionFind(n);
    for (const [u, v] of edges) uf.unite(u, v);
    return uf.connected(source, destination);
